package jp.tapmarker;
import android.app.*;import android.content.*;import android.net.ConnectivityManager;import android.net.Network;import android.net.NetworkCapabilities;import android.net.NetworkRequest;import android.net.nsd.*;import android.os.*;import android.provider.Settings;import android.view.*;import android.view.accessibility.*;import android.widget.*;import java.net.*;import java.util.*;import java.util.concurrent.*;import java.io.*;import io.github.muntashirakon.adb.*;
/** User-started, self-device-only wireless ADB bootstrap. Never automates OS authorization switches. */
final class WirelessAdb {
 final TapService s;final ExecutorService worker=Executors.newSingleThreadExecutor();volatile int generation;volatile boolean working,pairing,connecting;volatile PairingConnectionCtx pairingClient;volatile AdbConnection connection;volatile AdbStream stream;NsdManager nsd;NsdManager.DiscoveryListener discovery;final ArrayDeque<NsdServiceInfo> resolveQueue=new ArrayDeque<>();boolean resolving;int connectPort,lastTriedPort;long until;String attempted="";Runnable after;boolean settingsOpened;volatile String localToken;
 WirelessAdb(TapService s){this.s=s;modeListener=(p,key)->{if("automaticWifi".equals(key))this.s.h.post(()->applyMode());};}
 final WirelessModePolicy modePolicy=new WirelessModePolicy();boolean monitorStarted,destroyed,quiet;
 ConnectivityManager networkManager;ConnectivityManager.NetworkCallback networkCallback;
 final SharedPreferences.OnSharedPreferenceChangeListener modeListener;
 boolean automatic(){return s.getSharedPreferences("wirelessAdb",0).getBoolean("automaticWifi",false);}
 String modeLabel(){return automatic()?"Wi-Fi中は自動接続":"手動接続";}
 void setAutomatic(boolean enabled){s.getSharedPreferences("wirelessAdb",0).edit().putBoolean("automaticWifi",enabled).apply();}
 void modeDialog(){AlertDialog d=new UiStrings.DialogBuilder(s).setTitle("端末内接続モード").setSingleChoiceItems(new String[]{"Wi-Fi接続中は自動接続・維持","手動接続（自動接続しない）"},automatic()?0:1,(dialog,index)->{setAutomatic(index==0);dialog.dismiss();}).setNegativeButton("閉じる",null).create();d.getWindow().setType(WindowManager.LayoutParams.TYPE_ACCESSIBILITY_OVERLAY);d.show();}
 void startMonitor(){if(monitorStarted)return;monitorStarted=true;s.getSharedPreferences("wirelessAdb",0).registerOnSharedPreferenceChangeListener(modeListener);networkManager=(ConnectivityManager)s.getSystemService(Context.CONNECTIVITY_SERVICE);networkCallback=new ConnectivityManager.NetworkCallback(){public void onAvailable(Network n){s.h.post(pump);}public void onCapabilitiesChanged(Network n,NetworkCapabilities c){s.h.post(pump);}public void onLost(Network n){s.h.post(pump);}};try{if(networkManager!=null)networkManager.registerNetworkCallback(new NetworkRequest.Builder().addTransportType(NetworkCapabilities.TRANSPORT_WIFI).build(),networkCallback);}catch(Exception ignored){}applyMode();}
 void applyMode(){if(destroyed)return;modePolicy.mode(automatic());if(!automatic()){if(quiet)cancel();s.pilot.virtualWindows.cancelRecovery();note("端末内接続：手動モード / 接続済みの実行部は維持");}else note("端末内接続：Wi-Fi中は自動接続 / 初回のペア設定は必要です");s.h.removeCallbacks(pump);s.h.post(pump);}
 void pauseMaintenance(){modePolicy.pause();s.pilot.virtualWindows.cancelRecovery();cancel();}
 void resumeMaintenance(){modePolicy.resume();s.pilot.virtualWindows.recoveryBudget.reset();s.h.post(pump);}
 final Runnable pump=new Runnable(){public void run(){if(destroyed||!monitorStarted||Build.VERSION.SDK_INT<30)return;boolean wifi=wifiConnected(),connected=VirtualBridgeProvider.connected()!=null;if(connected){modePolicy.connected();if(!modePolicy.paused&&(automatic()||s.pilot.virtualWindows.recoverPending))s.pilot.virtualWindows.backendAvailable();}else if(modePolicy.shouldConnect(wifi,false,working,SystemClock.uptimeMillis())){modePolicy.attempted(SystemClock.uptimeMillis());bootstrap(false,true);}if(modePolicy.cancelForWifiLoss(wifi,working,quiet,connected)){cancel();modePolicy.failed(SystemClock.uptimeMillis());}s.h.removeCallbacks(this);s.h.postDelayed(this,2000);}};
 void note(String message){s.pilot.note(message);}
 void guide(boolean openWindows){if(Build.VERSION.SDK_INT<30){note("端末内接続にはAndroid11以降が必要です");return;}AlertDialog d=new UiStrings.DialogBuilder(s).setTitle("端末だけで接続").setMessage("PC・Shizukuは不要です。起動時にはWi-Fi接続が必要です。起動した実行部はADB接続から切り離します。起動済みの実行部はWi-Fi切断だけでは終了させません。実行部が終了した場合はWi-Fi復帰後に再接続し、実行中だった仮想画面を復旧します。USBデバッグはオンに保ってください（ケーブル接続は不要）。再起動やアプリの強制停止後は再度起動が必要です。\n\nワイヤレスデバッグを有効にし、「ペア設定コードを使用してデバイスをペア設定」を開いてください。表示されたコードと接続先をユーザー補助で読み取り、ペアリング・接続・実行部の起動を進めます。\n\n保存済みの鍵が使える場合は再ペアリングせず接続します。読み取り不可の場合は「接続情報を入力」を使えます。「全停止」で接続準備も取り消します。").setPositiveButton("接続を開始",(a,b)->begin(openWindows)).setNegativeButton("閉じる",null).create();d.getWindow().setType(WindowManager.LayoutParams.TYPE_ACCESSIBILITY_OVERLAY);d.show();}
 void begin(boolean openWindows){resumeMaintenance();s.stop();s.pilot.virtualWindows.close();bootstrap(openWindows,false);}
 void bootstrap(boolean openWindows,boolean silent){cancel();quiet=silent;working=true;pairing=false;connecting=false;int task=++generation;after=openWindows?()->s.pilot.virtualWindows.openAdb():null;connectPort=lastTriedPort=0;attempted="";settingsOpened=false;until=SystemClock.uptimeMillis()+(silent?30000:300000);
  IBinder existing=VirtualBridgeProvider.connected();if(existing!=null){VirtualProtocol backend=new VirtualProtocol(existing);boolean current=false;try{current=backend.implementation()==VirtualProtocol.IMPLEMENTATION;}catch(Exception ignored){}if(current){finish(task);return;}VirtualBridgeProvider.forget(existing);try{backend.shutdown();}catch(Exception ignored){}note("旧実行部を終了 / 更新済みAPKから接続し直します");}
  if(!wifiConnected()){cancel();note("実行部が未起動です / 起動時にはWi-Fi接続が必要です。通常画面の連打は利用できます");return;}
  note("端末内接続：接続先を探しています");discover(task);s.h.post(()->tick(task));if(!silent)s.h.postDelayed(()->{if(valid(task)&&!pairing&&!connecting&&connectPort==0)openSettings();},1500);
 }
 boolean valid(int task){return working&&generation==task;}
 boolean wifiConnected(){android.net.ConnectivityManager manager=(android.net.ConnectivityManager)s.getSystemService(Context.CONNECTIVITY_SERVICE);if(manager==null)return false;for(android.net.Network network:manager.getAllNetworks()){android.net.NetworkCapabilities caps=manager.getNetworkCapabilities(network);if(caps!=null&&caps.hasTransport(android.net.NetworkCapabilities.TRANSPORT_WIFI))return true;}return false;}
 void openSettings(){if(settingsOpened)return;settingsOpened=true;try{Intent direct=new Intent("android.settings.WIRELESS_DEBUGGING_SETTINGS").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);if(direct.resolveActivity(s.getPackageManager())!=null)s.startActivity(direct);else s.startActivity(new Intent(Settings.ACTION_APPLICATION_DEVELOPMENT_SETTINGS).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));note("ワイヤレスデバッグのペア設定コード画面を開いてください / 自動読み取り待ち");}catch(Exception e){note("開発者向けオプションからペア設定コード画面を開いてください");}}
 void tick(int task){if(!valid(task))return;if(SystemClock.uptimeMillis()>until){boolean silent=quiet;cancel();modePolicy.failed(SystemClock.uptimeMillis());note(silent?"端末内接続：接続先待ち / 間隔を空けて再試行":"端末内接続の待機を終了しました / 再開できます");return;}readSettings(task);s.h.postDelayed(()->tick(task),300);}
 void onEvent(AccessibilityEvent event){if(working&&"com.android.settings".contentEquals(event.getPackageName()==null?"":event.getPackageName()))s.h.post(()->readSettings(generation));}
 void readSettings(int task){if(!valid(task)||pairing||connecting)return;AccessibilityNodeInfo root=s.getRootInActiveWindow();if(root==null)return;try{String pkg=String.valueOf(root.getPackageName());if(!"com.android.settings".equals(pkg))return;ArrayList<String> texts=new ArrayList<>();collect(root,texts,new int[]{250});PairingInfo info=PairingInfo.parse(pkg,texts);texts.clear();if(info!=null){pair(task,info);return;}}finally{root.recycle();}}
 void collect(AccessibilityNodeInfo n,List<String> texts,int[] left){if(--left[0]<0)return;if(n.isVisibleToUser()&&n.getText()!=null)texts.add(n.getText().toString());for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo child=n.getChild(i);if(child!=null){try{collect(child,texts,left);}finally{child.recycle();}}}}
 static boolean ownAddress(String host)throws Exception{InetAddress a=InetAddress.getByName(host);return a.isLoopbackAddress()||NetworkInterface.getByInetAddress(a)!=null;}
 void pair(int task,PairingInfo info){if(!valid(task)||pairing||connecting)return;try{if(!ownAddress(info.host)){note("自分の端末以外の接続先にはペアリングしません");return;}}catch(Exception e){note("端末内の接続先を確認できません");return;}String fingerprint=info.port+":"+info.code;if(fingerprint.equals(attempted))return;attempted=fingerprint;pairing=true;note("ペア設定情報を読み取りました / ペアリング中");
  worker.execute(()->{PairingConnectionCtx client=null;try{if(!valid(task))return;WirelessKeys keys=WirelessKeys.load(s);client=new PairingConnectionCtx("127.0.0.1",info.port,info.code.getBytes("UTF-8"),keys.transportKey(),keys.cert,"TapMarker@android");pairingClient=client;if(!valid(task))return;client.start();s.h.post(()->{if(!valid(task))return;pairing=false;lastTriedPort=0;s.getSharedPreferences("wirelessAdb",0).edit().putBoolean("paired",true).apply();note("ペアリング成功 / 端末内接続を確認中");if(connectPort>0)connect(task,connectPort);});}catch(Exception error){s.h.post(()->{if(!valid(task))return;pairing=false;note("ペアリング失敗 / コード画面を開き直すか接続情報を入力してください");});}finally{if(client!=null)client.close();if(pairingClient==client)pairingClient=null;}});
 }
 void discover(int task){nsd=(NsdManager)s.getSystemService(Context.NSD_SERVICE);discovery=new NsdManager.DiscoveryListener(){public void onDiscoveryStarted(String type){}public void onStartDiscoveryFailed(String type,int error){s.h.post(()->{if(valid(task))note("接続先の自動検出に失敗 / 接続情報を入力できます");});}public void onDiscoveryStopped(String type){}public void onStopDiscoveryFailed(String type,int error){}public void onServiceLost(NsdServiceInfo info){}public void onServiceFound(NsdServiceInfo info){s.h.post(()->{if(valid(task)){resolveQueue.add(info);resolveNext(task);}});}};try{nsd.discoverServices("_adb-tls-connect._tcp.",NsdManager.PROTOCOL_DNS_SD,discovery);}catch(Exception e){note("接続先の自動検出に失敗 / 接続情報を入力できます");}}
 void resolveNext(int task){if(!valid(task)||resolving||resolveQueue.isEmpty())return;resolving=true;NsdServiceInfo info=resolveQueue.remove();try{nsd.resolveService(info,new NsdManager.ResolveListener(){public void onResolveFailed(NsdServiceInfo i,int error){s.h.post(()->{if(!valid(task))return;resolving=false;resolveNext(task);});}public void onServiceResolved(NsdServiceInfo i){s.h.post(()->{if(!valid(task))return;resolving=false;try{if(i.getHost()!=null&&ownAddress(i.getHost().getHostAddress())&&PairingInfo.validPort(i.getPort())){connectPort=i.getPort();if(!pairing&&!connecting&&s.getSharedPreferences("wirelessAdb",0).getBoolean("paired",false))connect(task,connectPort);}}catch(Exception ignored){}resolveNext(task);});}});}catch(Exception e){resolving=false;resolveNext(task);}}
 void connect(int task,int port){
  if(!valid(task)||pairing||connecting||lastTriedPort==port)return;
  lastTriedPort=port;connecting=true;localToken=UUID.randomUUID().toString().replace("-","");final String token=localToken;VirtualBridgeProvider.prepareLocal(token);note("端末内ADBに接続中");
  worker.execute(()->{AdbConnection current=null;AdbStream channel=null;boolean started=false;
   try{if(!valid(task))return;WirelessKeys keys=WirelessKeys.load(s);
    current=new AdbConnection.Builder("127.0.0.1",port).setApi(Build.VERSION.SDK_INT).setPrivateKey(keys.transportKey()).setCertificate(keys.cert).setDeviceName("TapMarker@android").build();connection=current;
    if(!valid(task))return;if(!current.connect(12,TimeUnit.SECONDS,true))throw new IOException("接続待機を終了");if(!valid(task))return;
    channel=current.open(LocalLaunch.command(s.getApplicationInfo().sourceDir,token));stream=channel;
    InputStream input=channel.openInputStream();ByteArrayOutputStream line=new ByteArrayOutputStream();byte[] bytes=new byte[256];boolean confirmed=false;int count=0;
    ScheduledExecutorService timeout=Executors.newSingleThreadScheduledExecutor();final AdbStream cancelStream=channel;timeout.schedule(()->{try{cancelStream.close();}catch(Exception ignored){}},15,TimeUnit.SECONDS);
    try{while(valid(task)&&count<8192){int n=input.read(bytes);if(n<0)break;count+=n;line.write(bytes,0,n);String output=line.toString("UTF-8");if(output.contains("TAPMARKER_ADB_CONNECTED")){confirmed=true;break;}if(output.contains("TAPMARKER_ADB_ERROR"))break;}}finally{timeout.shutdownNow();}
    if(!confirmed)throw new IOException("実行部の起動を確認できません");started=true;
   }catch(Exception error){if(valid(task)&&VirtualBridgeProvider.localConnected(token)){started=true;}else{VirtualBridgeProvider.cancelLocal(token);final String reason=error instanceof AdbPairingRequiredException||error instanceof AdbAuthenticationFailedException?"再ペアリングが必要です":"接続または実行部の起動を確認できません";
    s.h.post(()->{if(valid(task)){connecting=false;note(reason+" / ペア設定コード画面または接続情報入力を使ってください");if(quiet){cancel();modePolicy.failed(SystemClock.uptimeMillis());}else openSettings();}});
    }
   }finally{
    if(channel!=null)try{channel.close();}catch(Exception ignored){}if(current!=null)try{current.close();}catch(Exception ignored){}
    if(stream==channel)stream=null;if(connection==current)connection=null;
    if(started)s.h.postDelayed(()->{if(valid(task))awaitBridge(task,0);else VirtualBridgeProvider.cancelLocal(token);},400);
   }
  });
 }
 void awaitBridge(int task,int attempt){if(!valid(task))return;if(VirtualBridgeProvider.connected()!=null){finish(task);return;}if(attempt>=30){cancel();modePolicy.failed(SystemClock.uptimeMillis());note("端末内実行部とAPKの接続を確認できません / 再試行待ち");return;}s.h.postDelayed(()->awaitBridge(task,attempt+1),100);}
 void finish(int task){if(!valid(task))return;Runnable next=after;after=null;VirtualBridgeProvider.finishLocal(localToken);localToken=null;working=false;pairing=connecting=false;attempted="";stopDiscovery();modePolicy.connected();note(VirtualBridgeProvider.localDetached()?"端末内実行部を起動 / ADB接続は切断済み":"既存のADB実行部を使用しています");if(next!=null)next.run();else s.pilot.virtualWindows.backendAvailable();}
 void input(){LinearLayout layout=new LinearLayout(s);layout.setOrientation(1);EditText port=new EditText(s);UiStrings.hint(port,"ポート番号（コード画面または接続画面）");port.setInputType(2);layout.addView(port);EditText code=new EditText(s);UiStrings.hint(code,"ペア設定コード6桁 / 接続済みなら空欄");code.setInputType(18);layout.addView(code);AlertDialog d=new UiStrings.DialogBuilder(s).setTitle("端末内の接続情報を入力").setMessage("ペアリング用と接続用のポートは別です。コードは保存しません。接続先は自分の端末に固定します。").setView(layout).setPositiveButton("実行",(a,b)->{try{int number=Integer.parseInt(port.getText().toString());String secret=code.getText().toString().trim();code.setText("");if(!PairingInfo.validPort(number)||!secret.isEmpty()&&!PairingInfo.validCode(secret))throw new IllegalArgumentException();if(!working)begin(false);attempted="";if(secret.isEmpty()){lastTriedPort=0;connect(generation,number);}else pair(generation,new PairingInfo("127.0.0.1",number,secret));}catch(Exception e){note("ポート番号と6桁コードを確認してください");}}).setNegativeButton("閉じる",(a,b)->code.setText("")).create();d.getWindow().setType(WindowManager.LayoutParams.TYPE_ACCESSIBILITY_OVERLAY);d.show();}
 void stopDiscovery(){NsdManager.DiscoveryListener current=discovery;discovery=null;resolveQueue.clear();resolving=false;if(current!=null&&nsd!=null)try{nsd.stopServiceDiscovery(current);}catch(Exception ignored){}}
 void cancel(){if(!working)return;working=false;generation++;after=null;VirtualBridgeProvider.cancelLocal(localToken);localToken=null;pairing=connecting=false;attempted="";stopDiscovery();PairingConnectionCtx p=pairingClient;pairingClient=null;if(p!=null)p.abort();AdbConnection c=connection;connection=null;AdbStream channel=stream;stream=null;worker.execute(()->{if(channel!=null)try{channel.close();}catch(Exception ignored){}if(c!=null)try{c.close();}catch(Exception ignored){}});}
 void destroy(){destroyed=true;s.h.removeCallbacks(pump);s.getSharedPreferences("wirelessAdb",0).unregisterOnSharedPreferenceChangeListener(modeListener);if(networkCallback!=null&&networkManager!=null)try{networkManager.unregisterNetworkCallback(networkCallback);}catch(Exception ignored){}cancel();VirtualBridgeProvider.closeLocal();AdbStream channel=stream;AdbConnection c=connection;stream=null;connection=null;worker.execute(()->{if(channel!=null)try{channel.close();}catch(Exception ignored){}if(c!=null)try{c.close();}catch(Exception ignored){}});worker.shutdown();}
}
